{
  "titre": "Mitose et méiose : distinguer les processus",
  "objectifGeneral": "Distinguer les mécanismes et les enjeux de la mitose et de la méiose",
  "notionsPivots": [
    "la mitose",
    "la méiose",
    "les cellules somatiques",
    "les cellules germinales",
    "la division cellulaire",
    "le cycle cellulaire",
    "la recombinaison génétique",
    "les chromosomes homologues",
    "les gamètes",
    "la diversité génétique"
  ],
  "etapes": [
    {
      "titre": "Découverte des processus",
      "objectif": "Identifier les caractéristiques principales de la mitose et de la méiose",
      "cartes": [
        {
          "titre": "Présentation des concepts",
          "objectif": "Découvrir les définitions de la mitose et de la méiose",
          "module": "CoursePresentation",
          "palier": "decouverte",
          "duree": 15,
          "consigne": "Lisez attentivement la présentation qui introduit les notions de mitose et de méiose. Notez les différences clés entre ces deux processus."
        },
        {
          "titre": "Lexique des termes",
          "objectif": "S'approprier le vocabulaire spécifique",
          "module": "Glossary",
          "palier": "decouverte",
          "duree": 10,
          "consigne": "Consultez le glossaire pour comprendre les termes clés comme 'cellules somatiques', 'gamètes', 'recombinaison génétique' ou 'chromosomes homologues'."
        }
      ]
    },
    {
      "titre": "Comparaison des mécanismes",
      "objectif": "Comparer les étapes et les produits de la mitose et de la méiose",
      "cartes": [
        {
          "titre": "Frise des étapes",
          "objectif": "Ordonner les phases de la mitose et de la méiose",
          "module": "SortParagraphs",
          "palier": "entrainement",
          "duree": 20,
          "consigne": "À partir des descriptions fournies, replacez dans l'ordre les étapes de la mitose et celles de la méiose. Travaillez en binôme pour discuter vos choix."
        },
        {
          "titre": "Quiz de comparaison",
          "objectif": "Valider la compréhension des différences",
          "module": "QuizSetQCM",
          "palier": "entrainement",
          "duree": 15,
          "consigne": "Répondez au quiz qui teste votre capacité à distinguer les caractéristiques de la mitose et de la méiose. Une seule réponse est correcte par question."
        }
      ]
    },
    {
      "titre": "Application et entraînement",
      "objectif": "Appliquer les connaissances à des cas concrets",
      "cartes": [
        {
          "titre": "Exercices de classification",
          "objectif": "Classer des événements ou des produits selon le type de division",
          "module": "DragAndDrop",
          "palier": "entrainement",
          "duree": 20,
          "consigne": "Glissez les étiquettes dans les bonnes catégories : 'mitose' ou 'méiose'. Par exemple, associez 'cellules somatiques' à la mitose et 'gamètes' à la méiose."
        },
        {
          "titre": "Étude de cas",
          "objectif": "Analyser un exemple de division cellulaire",
          "module": "InteractiveBook",
          "palier": "entrainement",
          "duree": 25,
          "consigne": "Lisez le cas pratique présenté dans le livre interactif. Identifiez s'il s'agit d'une mitose ou d'une méiose et justifiez votre réponse en vous appuyant sur les critères vus."
        }
      ]
    },
    {
      "titre": "Synthèse et évaluation",
      "objectif": "Synthétiser les connaissances et évaluer sa compréhension",
      "cartes": [
        {
          "titre": "Synthèse collective",
          "objectif": "Construire une synthèse partagée des différences",
          "module": "Summary",
          "palier": "transfert",
          "duree": 20,
          "consigne": "À partir des réponses du groupe, choisissez les affirmations correctes pour construire une synthèse collective des différences entre mitose et méiose."
        },
        {
          "titre": "Quiz final",
          "objectif": "Évaluer sa maîtrise des notions",
          "module": "QuizSet",
          "palier": "transfert",
          "duree": 15,
          "consigne": "Passez le quiz final qui évalue votre compréhension globale de la mitose et de la méiose. Les questions portent sur les notions pivots du parcours."
        }
      ]
    }
  ]
}
